  // Request-time APIs can't be called inside `after` in a Server Component,
  // so read the request data during render and pass it in via closure.
  const requestHeaders = await headers()
  const userAgent = requestHeaders.get('user-agent') ?? 'unknown'
  const referrer = requestHeaders.get('referer')

  // Runs after the response has been sent, so it never blocks rendering.
  after(async () => {
    await logPageView({
      path: '/',
      userAgent,
      referrer,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
